//! PdfCraft on phones: the engine as a native library for the Android app in `android/`, with
//! bindings generated by [UniFFI](https://mozilla.github.io/uniffi-rs).
//!
//! The phone UI is one more frontend next to the desktop app, the CLI/MCP server and the web
//! build. It runs the engine's headless tools by name ([`MobileSession::execute`]: the same tools
//! and JSON arguments as `pdfcraft-cli run` and MCP, `pdfcraft-cli tools` lists them) and asks for
//! pixels ([`MobileSession::render_page`]). A few typed helpers (documents, pages, outline) save
//! the UI from parsing JSON for what it shows all the time.
//!
//! Threading: every method may be called from any thread, and the ones that render block, so the
//! UI calls them off its main thread. A render holds the session lock only to look up the
//! document's bytes; the page is drawn unlocked by a renderer of its own, so the UI can keep
//! running tools (and other renders) while one is in flight.
#![forbid(unsafe_code)]
#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::unimplemented, clippy::todo, clippy::unreachable)]

use std::collections::HashMap;
use std::sync::{
    Arc, Mutex, MutexGuard, PoisonError,
    atomic::{AtomicBool, Ordering},
};

use pdfcraft_automation::{Automation, Content, ToolError};
use pdfcraft_engine::{DocId, Document};
use pdfcraft_render::{OpenError, PageRenderer, PageText, RenderConfig, RenderRequest, RequestKind, Tile};
use serde_json::{Value, json};

uniffi::setup_scaffolding!();

