/// The app's private files directory, once the session is told it: thumbnails of working copies
/// stored there are drawn from a read-only mapping.
static PRIVATE_INPUT_ROOT: std::sync::OnceLock<std::path::PathBuf> = std::sync::OnceLock::new();

/// Page 1 of the PDF at absolute path `path` drawn to fit `max_side` pixels, for file lists. The
/// file is read but not opened in any session; a protected or unreadable file is an error.
#[uniffi::export]
pub fn file_thumbnail(path: String, max_side: u32) -> Result<RenderedImage, MobileError> {
    // File-list previews must not allocate another full large-PDF input beside an open viewer.
    // A working copy in the app's private store is mapped instead, at any size the viewer opens;
    // other files keep the 100 MiB preview limit (a 336 MB working copy had lost its thumbnail).
    let root = PRIVATE_INPUT_ROOT.get().map(std::path::PathBuf::as_path);
    let bytes = pdfcraft_cos::read_private_preview(std::path::Path::new(&path), root, 512 * 1024 * 1024, 100 * 1024 * 1024)
        .map_err(|e| MobileError::Open(format!("{path}: {e}")))?;
    let mut r = PageRenderer::new(bytes, RenderConfig::default());
    if r.page_count() == 0 {
        return Err(MobileError::Open("the file has no pages".into()));
    }
    // a first, tiny render gives the page's aspect; the real one fits it into max_side
    let probe = r.render(RenderRequest { page: 0, kind: RequestKind::Pixels, tile: None, scale: 0.05, tag: 0, preview: true });
    if let Some(e) = probe.error {
        return Err(MobileError::Render(e));
    }
    let (w, h) = (probe.width.max(1) as f32 / 0.05, probe.height.max(1) as f32 / 0.05);
    let scale = (max_side.clamp(16, 2048) as f32 / w.max(h)).max(0.01);
    let out = r.render(RenderRequest { page: 0, kind: RequestKind::Pixels, tile: None, scale, tag: 0, preview: true });
    if let Some(e) = out.error {
        return Err(MobileError::Render(e));
    }
    Ok(RenderedImage { width: out.width, height: out.height, rgba: out.rgba.to_vec() })
}

/// A digital ID file's certificate, as the app lists the IDs it can sign with.
#[derive(Debug, Clone, uniffi::Record)]
pub struct DigitalIdInfo {
    /// Whose it is (the certificate's common name, else its whole subject).
    pub name: String,
    pub issuer: String,
    pub email: Option<String>,
    /// When it starts and stops being valid (seconds since 1970).
    pub valid_from: i64,
    pub valid_to: i64,
    pub self_signed: bool,
    /// The certificate's SHA-256 fingerprint (hex), which tells IDs apart.
    pub sha256: String,
    /// Why it can't sign documents, if it can't (its key usage doesn't allow it).
    pub problem: Option<String>,
}

/// The largest digital ID file read: real ones are a few kilobytes.
const MAX_ID_FILE: u64 = 1 << 20;

/// What the digital ID file (.p12 / .pfx) at absolute path `path` holds, unlocked with
/// `password`: a wrong password is [`MobileError::WrongPassword`].
#[uniffi::export]
pub fn digital_id_info(path: String, password: String) -> Result<DigitalIdInfo, MobileError> {
    use pdfcraft_engine::sign::{SignError, pkcs12};
    let size = std::fs::metadata(&path).map_err(|e| MobileError::Command(format!("{path}: {e}")))?.len();
    if size > MAX_ID_FILE {
        return Err(MobileError::Command("this is not a digital ID file (it is too large)".into()));
    }
    let bytes = std::fs::read(&path).map_err(|e| MobileError::Command(format!("{path}: {e}")))?;
    let id = pkcs12::open(&bytes, &password).map_err(|e| match e {
        SignError::WrongPassword => MobileError::WrongPassword,
        e => MobileError::Command(e.to_string()),
    })?;
    let c = &id.certificate;
    Ok(DigitalIdInfo {
        name: c.display_name(),
        issuer: c.issuer.display(),
        email: c.subject.email().map(str::to_string),
        valid_from: c.not_before.unix(),
        valid_to: c.not_after.unix(),
        self_signed: c.is_self_signed(),
        sha256: c.fingerprint(),
        problem: c.signing_problem().map(|d| d.message),
    })
}

/// The engine version (`0.6.0`).
#[uniffi::export]
pub fn engine_version() -> String {
    env!("CARGO_PKG_VERSION").into()
}

/// Send the engine's log to logcat (Android; elsewhere it does nothing). Safe to call repeatedly.
#[uniffi::export]
pub fn init_logging() {
    #[cfg(target_os = "android")]
    android_logger::init_once(android_logger::Config::default().with_max_level(log::LevelFilter::Info).with_tag("PdfCraft"));
}

