/// A rectangle in PDF user space as the page shows it (view space: points, y down).
fn view_rect(p: &pdfcraft_render::PageInfo, r: [f32; 4]) -> Vec<f32> {
    let [ax, ay] = p.user_to_view(r[0], r[1]);
    let [bx, by] = p.user_to_view(r[2], r[3]);
    vec![ax.min(bx), ay.min(by), ax.max(bx), ay.max(by)]
}

/// The paragraphs of `text` (see [`MobileSession::reading_blocks`]).
fn reading_blocks(text: &PageText, page: u32) -> Vec<ReadingBlock> {
    // each line's glyph span and box
    let mut lines: Vec<(usize, usize, f32, f32)> = Vec::new();
    for (i, g) in text.glyphs.iter().enumerate() {
        let line = text.line_of.get(i).copied().unwrap_or(0);
        match lines.last_mut() {
            Some(l) if text.line_of.get(l.0).copied() == Some(line) => {
                l.1 = i;
                l.2 = l.2.min(g.rect[1]);
                l.3 = l.3.max(g.rect[3]);
            }
            _ => lines.push((i, i, g.rect[1], g.rect[3])),
        }
    }
    let mut blocks: Vec<ReadingBlock> = Vec::new();
    let mut current: Option<(usize, usize, f32, f32)> = None;
    let flush = |c: Option<(usize, usize, f32, f32)>, blocks: &mut Vec<ReadingBlock>| {
        let Some((start, end, _, _)) = c else { return };
        let mut out = String::new();
        let mut map = Vec::new();
        for i in start..=end {
            let Some(g) = text.glyphs.get(i) else { continue };
            let new_line = i > start && text.line_of.get(i) != text.line_of.get(i - 1);
            if (new_line || text.space_before.get(i).copied().unwrap_or(false)) && !out.ends_with(' ') {
                out.push(' ');
                map.push(u32::try_from(i).unwrap_or(u32::MAX));
            }
            for ch in g.text.chars() {
                out.push(ch);
                map.push(u32::try_from(i).unwrap_or(u32::MAX));
            }
        }
        let trimmed = out.trim_end();
        if !trimmed.is_empty() {
            map.truncate(trimmed.chars().count());
            blocks.push(ReadingBlock {
                text: trimmed.to_string(),
                range: TextRange { page, start: start as u32, end: end.saturating_add(1) as u32 },
                glyph_of_char: map,
            });
        }
    };
    for &(s, e, top, bottom) in &lines {
        let height = (bottom - top).max(0.1);
        current = match current {
            Some((cs, _, ctop, cbottom)) => {
                let prev_height = (cbottom - ctop).max(0.1);
                let gap = top - cbottom;
                let breaks = gap > prev_height * 0.5 || top < ctop - prev_height * 0.5 || (height / prev_height - 1.0).abs() > 0.3;
                if breaks {
                    flush(current, &mut blocks);
                    Some((s, e, top, bottom))
                } else {
                    Some((cs, e, top, bottom))
                }
            }
            None => Some((s, e, top, bottom)),
        };
    }
    flush(current, &mut blocks);
    blocks
}

fn rgb(c: [f32; 3]) -> u32 {
    let ch = |v: f32| (v.clamp(0.0, 1.0) * 255.0).round() as u32;
    (ch(c[0]) << 16) | (ch(c[1]) << 8) | ch(c[2])
}

/// How many idle renderers a document keeps (a page view and its thumbnails can render at once).
const RENDERERS_PER_DOC: usize = 3;

#[derive(Debug, Clone, uniffi::Record)]
pub struct PageOverlays {
    pub generation: u64,
    pub pages: Vec<u32>,
    pub comments: Vec<CommentInfo>,
    pub widgets: Vec<WidgetInfo>,
}

/// Avoid multiple 64-megapixel Rust/JNA/Bitmap copies on a phone. Hi-res zoom uses 512px tiles.
const MAX_MOBILE_PAGE_PIXELS: u64 = 4 * 1024 * 1024;
const MAX_MOBILE_TILE_PIXELS: u64 = 1024 * 1024;

/// The documents' idle renderers: the bytes they render, the view settings they were built with
/// ([`config_key`]), and the renderers themselves.
type RendererCache = HashMap<u64, (pdfcraft_cos::PdfBytes, String, Vec<PageRenderer>)>;

/// A document's text layers: the bytes they were taken from, a renderer to extract more, and one
/// slot per page.
struct TextCache {
    bytes: pdfcraft_cos::PdfBytes,
    renderer: PageRenderer,
    pages: Vec<Option<Arc<PageText>>>,
}

/// The engine's session: the open documents, their edit history and the tools that act on them.
#[derive(uniffi::Object)]
pub struct MobileSession {
    auto: Mutex<Automation>,
    renderers: Mutex<RendererCache>,
    texts: Mutex<HashMap<u64, TextCache>>,
    pending_opens: Mutex<HashMap<u64, PendingOpen>>,
    private_input_root: std::sync::OnceLock<std::path::PathBuf>,
}

struct PendingOpen {
    context: pdfcraft_engine::OpenContext,
    name: String,
    path: String,
    bytes: pdfcraft_cos::PdfBytes,
    password: Option<String>,
    trace: pdfcraft_render::OpenTrace,
    cancelled: Arc<AtomicBool>,
}

impl MobileSession {
    fn lock(&self) -> MutexGuard<'_, Automation> {
        self.auto.lock().unwrap_or_else(|poisoned| {
            // Everything that changes the session runs through `with_auto`, which catches a panic
            // while the lock is still held, so only a read (`with_doc`) or cache bookkeeping can
            // poison it, and neither leaves the documents half-changed (#114).
            log::warn!("recovering the engine session after a panic in a read-only call");
            self.auto.clear_poison();
            poisoned.into_inner()
        })
    }

    /// Run `f` on the session under its lock. A panic in the engine (say on a malformed PDF) is
    /// caught while the lock is held, so it neither poisons the session nor crosses the FFI as an
    /// `InternalException` the app does not expect: `what` fails with [`MobileError::Command`]
    /// instead (#114).
    fn with_auto<T>(&self, what: &str, f: impl FnOnce(&mut Automation) -> Result<T, MobileError>) -> Result<T, MobileError> {
        let mut auto = self.lock();
        catch_panic(what, || {
            #[cfg(test)]
            tests::inject_panic(what);
            f(&mut auto)
        })
    }

    fn cache(&self) -> MutexGuard<'_, RendererCache> {
        self.renderers.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// Run tool `name`; its JSON result (`null` if it gave none).
    fn call(&self, name: &str, args: &Value) -> Result<Value, MobileError> {
        self.with_auto(name, |auto| {
            if name != "doc_close" && name != "doc_list" && auto.session().docs().iter().any(Document::preparing) {
                return Err(MobileError::Command("Document preparation is still running".into()));
            }
            let out = auto.call(name, args).map_err(|e| MobileError::Command(e.to_string()))?;
            Ok(first_json(out))
        })
    }

    /// An idle renderer for `bytes`, or a new one.
    fn take_renderer(&self, doc: u64, bytes: &pdfcraft_cos::PdfBytes, config: RenderConfig) -> PageRenderer {
        let mut cache = self.cache();
        // A renderer keeps the settings it was built with, so one built before a view change
        // (hide comments, layers, reading colours) is not reused after it (#122).
        let key = config_key(&config);
        match cache.get_mut(&doc) {
            Some((b, k, idle)) if pdfcraft_cos::same_storage(b, bytes) && *k == key => idle.pop(),
            _ => None,
        }
        .unwrap_or_else(|| PageRenderer::new(bytes.clone(), config))
    }

    /// Give a renderer back for the next render, unless the document has changed since.
    fn return_renderer(&self, doc: u64, bytes: &pdfcraft_cos::PdfBytes, config: &RenderConfig, renderer: PageRenderer) {
        // Keep a late reading-stage render from reviving a closed or superseded cache entry.
        let auto = self.lock();
        if !auto.session().get(DocId(doc)).is_some_and(|d| pdfcraft_cos::same_storage(&d.display, bytes)) {
            return;
        }
        let mut cache = self.cache();
        let key = config_key(config);
        let entry = cache.entry(doc).or_insert_with(|| (bytes.clone(), key.clone(), Vec::new()));
        if !pdfcraft_cos::same_storage(&entry.0, bytes) || entry.1 != key {
            // the renderers of an older version of the document, or of older view settings, are
            // no use any more
            *entry = (bytes.clone(), key, Vec::new());
        }
        if entry.2.len() < RENDERERS_PER_DOC {
            entry.2.push(renderer);
        }
    }

    fn overlay_snapshot(&self, doc: u64, pages: Option<&[usize]>) -> Result<pdfcraft_engine::OverlaySnapshot, MobileError> {
        self.with_doc(doc, |d| d.overlay_snapshot(pages))?.ok_or_else(|| MobileError::Command("Document preparation is still running".into()))
    }

    fn render_pixels(&self, doc: u64, page: u32, scale: f32, tile: Option<TileRect>) -> Result<pdfcraft_render::RenderedPage, MobileError> {
        if !(scale.is_finite() && scale > 0.0) {
            return Err(MobileError::Render(format!("the scale must be a positive number, not {scale}")));
        }
        let index = page as usize;
        let (bytes, config, pages, size, ready) = self.with_render_config(doc, |d, config| {
            (d.display.clone(), config, d.info.pages.len(), d.info.pages.get(index).map(|p| (p.width, p.height)), d.reading_page_ready(index))
        })?;
        if !ready {
            return Err(MobileError::Render("This page is waiting for document preparation".into()));
        }
        let Some((width, height)) = size else {
            return Err(MobileError::Render(format!("page {} is out of range: the document has {pages} pages", index.saturating_add(1))));
        };
        let max_pixels = if let Some(t) = tile.as_ref() {
            let count = u64::from(t.width).saturating_mul(u64::from(t.height));
            if count == 0 || count > MAX_MOBILE_TILE_PIXELS {
                return Err(MobileError::Render("the requested tile is empty or too large for mobile rendering".into()));
            }
            MAX_MOBILE_TILE_PIXELS
        } else {
            MAX_MOBILE_PAGE_PIXELS
        };
        let mobile_scale = if tile.is_none() {
            // Keep two concurrent page rasters comfortably below the Android heap budget.
            // The 2% headroom accounts for ceil-to-pixel rounding on both axes.
            let area = width.max(1.0) * height.max(1.0);
            let cap = ((MAX_MOBILE_PAGE_PIXELS as f32 * 0.98) / area).sqrt();
            if !cap.is_finite() || cap <= 0.0 {
                return Err(MobileError::Render("the page's dimensions exceed mobile rendering limits".into()));
            }
            scale.min(cap)
        } else {
            scale
        };
        let mut renderer = self.take_renderer(doc, &bytes, config.clone());
        let raster_tile = tile.map(|t| Tile { x: t.x, y: t.y, w: t.width, h: t.height });
        let out =
            renderer.render(RenderRequest { page: index, kind: RequestKind::Pixels, tile: raster_tile, scale: mobile_scale, tag: 0, preview: false });
        self.return_renderer(doc, &bytes, &config, renderer);
        if let Some(e) = out.error {
            return Err(MobileError::Render(format!("page {} could not be drawn: {e}", index.saturating_add(1))));
        }
        let pixels = u64::from(out.width).saturating_mul(u64::from(out.height));
        if pixels == 0 || pixels > max_pixels || (out.rgba.len() as u64) != pixels.saturating_mul(4) {
            return Err(MobileError::Render("the renderer returned an invalid or oversized pixel buffer".into()));
        }
        Ok(out)
    }

    fn open_document(&self, path: String, password: Option<String>, recording: bool) -> Result<ProfiledOpen, MobileError> {
        if !std::path::Path::new(&path).is_absolute() {
            return Err(MobileError::Open(format!("the path must be absolute, not `{path}`")));
        }
        let mut args = json!({ "path": path, "open_timings": recording });
        if let (Some(password), Some(args)) = (password, args.as_object_mut()) {
            args.insert("password".into(), Value::String(password));
        }
        let out = first_json(self.with_auto("doc_open", |auto| auto.call("doc_open", &args).map_err(open_error))?);
        let id = out.get("doc").and_then(Value::as_u64).ok_or_else(|| MobileError::Open("the document did not open".into()))?;
        let timings = out
            .get("open_timings")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|s| Some(NativeOpenTiming { stage: s.get("stage")?.as_str()?.to_owned(), duration_ms: s.get("duration_ms")?.as_u64()? }))
            .collect();
        Ok(ProfiledOpen { document: self.document(id)?, timings })
    }

    /// [`with_doc`](Self::with_doc), with the configuration page rasters of `doc` use now.
    fn with_render_config<T>(&self, doc: u64, f: impl FnOnce(&Document, RenderConfig) -> T) -> Result<T, MobileError> {
        let a = self.lock();
        let session = a.session();
        let d = session.get(DocId(doc)).ok_or(MobileError::NoDocument(doc))?;
        let view = session.render_config(DocId(doc)).unwrap_or_default();
        Ok(f(d, page_render_config(d, &view)))
    }

    fn with_doc<T>(&self, doc: u64, f: impl FnOnce(&Document) -> T) -> Result<T, MobileError> {
        let a = self.lock();
        let d = a.session().get(DocId(doc)).ok_or(MobileError::NoDocument(doc))?;
        Ok(f(d))
    }

    /// The text layer of page `page` of `doc` as it is now (extracted once per document version).
    fn page_text(&self, doc: u64, page: u32) -> Result<Arc<PageText>, MobileError> {
        if self.with_doc(doc, Document::preparing)? {
            return Err(MobileError::Command("Document preparation is still running".into()));
        }
        let (bytes, password, pages) = self.with_doc(doc, |d| (d.bytes.clone(), d.password.clone(), d.info.pages.len()))?;
        let index = page as usize;
        if index >= pages {
            return Err(MobileError::Command(format!("page {} is out of range: the document has {pages} pages", index.saturating_add(1))));
        }
        let mut texts = self.texts.lock().unwrap_or_else(PoisonError::into_inner);
        let fresh = || TextCache {
            bytes: bytes.clone(),
            renderer: PageRenderer::new(bytes.clone(), RenderConfig { password: password.as_deref().map(Arc::from), ..RenderConfig::default() }),
            pages: vec![None; pages],
        };
        let entry = texts.entry(doc).or_insert_with(fresh);
        if !pdfcraft_cos::same_storage(&entry.bytes, &bytes) || entry.pages.len() != pages {
            *entry = fresh();
        }
        if let Some(Some(t)) = entry.pages.get(index) {
            return Ok(t.clone());
        }
        let out = entry.renderer.render(RenderRequest { page: index, kind: RequestKind::Text, tile: None, scale: 1.0, tag: 0, preview: false });
        let text = match (out.error, out.text) {
            (None, Some(t)) => t,
            (Some(e), _) => return Err(MobileError::Command(format!("the text of page {} could not be read: {e}", index.saturating_add(1)))),
            (None, None) => Arc::new(PageText::default()),
        };
        if let Some(slot) = entry.pages.get_mut(index) {
            *slot = Some(text.clone());
        }
        Ok(text)
    }
}

/// `start..end` clamped to the glyphs of `text`.
fn glyph_range(text: &PageText, start: u32, end: u32) -> std::ops::Range<usize> {
    let n = text.glyphs.len();
    let s = (start as usize).min(n);
    let e = (end as usize).clamp(s, n);
    s..e
}

fn flatten_rects(rects: &[[f32; 4]]) -> Vec<f32> {
    rects.iter().flat_map(|r| r.iter().copied()).collect()
}

#[uniffi::export]
impl MobileSession {
    /// A session with no documents open.
    #[uniffi::constructor]
    #[allow(clippy::new_without_default)]
    pub fn new() -> Arc<Self> {
        Arc::new(MobileSession {
            auto: Mutex::new(Automation::new()),
            renderers: Mutex::new(HashMap::new()),
            texts: Mutex::new(HashMap::new()),
            pending_opens: Mutex::new(HashMap::new()),
            private_input_root: std::sync::OnceLock::new(),
        })
    }

    /// Open the PDF at absolute path `path` (with `password` if it needs one).
    pub fn open(&self, path: String, password: Option<String>) -> Result<DocumentInfo, MobileError> {
        self.open_document(path, password, false).map(|opened| opened.document)
    }

    /// The same open path, with a bounded, request-local stage trace for Diagnostics.
    pub fn open_with_timings(&self, path: String, password: Option<String>) -> Result<ProfiledOpen, MobileError> {
        self.open_document(path, password, true)
    }

    /// Set only from the Android application context. The input layer validates private
    /// ownership and managed-store containment independently before allowing a mapping.
    pub fn set_private_input_root(&self, root: String) {
        let path = std::path::PathBuf::from(root);
        if path.is_absolute() && self.private_input_root.set(path.clone()).is_ok() {
            // file-list thumbnails (`file_thumbnail`) map working copies from the same store
            let _ = PRIVATE_INPUT_ROOT.set(path.clone());
            self.lock().set_private_input_root(path);
        }
    }

    /// Open a conservative reading stage, or retain complete opening for complex pages.
    /// The same immutable input is retained through background completion.
    pub fn begin_open(&self, path: String, password: Option<String>, initial_page: u32, recording: bool) -> Result<ProfiledOpen, MobileError> {
        if !std::path::Path::new(&path).is_absolute() {
            return Err(MobileError::Open("the path must be absolute".into()));
        }
        let trace = if recording { pdfcraft_render::OpenTrace::recording() } else { Default::default() };
        let (path, bytes, context) = {
            let auto = self.lock();
            let (path, bytes) = trace
                .measure("native_file_read", || auto.read_open_input_private(&path, self.private_input_root.get().map(|p| p.as_path())))
                .map_err(open_error)?;
            trace.event(if bytes.is_mapped() { "native_input_mapped" } else { "native_input_owned" });
            (path, bytes, auto.session().open_context())
        };
        let path = path.to_string_lossy().into_owned();
        let name = std::path::Path::new(&path).file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
        let cancelled = Arc::new(AtomicBool::new(false));
        let context = context.with_open_trace(trace.clone()).with_open_cancellation(cancelled.clone());
        let preview = trace
            .measure("native_reading_prepare", || {
                context.prepare_reading(name.clone(), Some(path.clone()), bytes.clone(), password.as_deref(), initial_page as usize)
            })
            .map_err(open_native_error)?;
        let (mut prepared, pending) = match preview {
            Some(prepared) => (prepared, true),
            None => (
                trace
                    .measure("native_prepare", || context.prepare_open(name.clone(), Some(path.clone()), bytes.clone(), password.as_deref()))
                    .map_err(open_native_error)?,
                false,
            ),
        };
        let parsed = prepared.take_parsed();
        let id = self.with_auto("doc_open", |auto| Ok(auto.register_prepared(prepared)))?.0;
        // The reading stage parsed the file for its page sizes; the first page render starts from
        // that parse instead of making it again (#212).
        if let Some(parsed) = parsed
            && let Ok((display, config)) = self.with_render_config(id, |d, config| (d.display.clone(), config))
        {
            self.return_renderer(id, &display, &config, PageRenderer::from_parsed(display.clone(), config.clone(), parsed));
        }
        if pending {
            self.pending_opens
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .insert(id, PendingOpen { context, name, path, bytes, password, trace: trace.clone(), cancelled });
        }
        Ok(ProfiledOpen { document: self.document(id)?, timings: native_stages(&trace, 0) })
    }

    /// Complete preparation away from the session lock. Closing the reading stage cancels it;
    /// a late result can never register a replacement document or revive a closed handle.
    pub fn complete_open(&self, doc: u64) -> Result<ProfiledOpen, MobileError> {
        let work = self
            .pending_opens
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .remove(&doc)
            .ok_or_else(|| MobileError::Command("No pending document preparation".into()))?;
        let start = work.trace.snapshot().len();
        if work.cancelled.load(Ordering::Acquire) {
            return Err(MobileError::NoDocument(doc));
        }
        let prepared = work
            .trace
            .measure("native_background_prepare", || work.context.prepare_open(work.name, Some(work.path), work.bytes, work.password.as_deref()))
            .map_err(open_native_error)?;
        if work.cancelled.load(Ordering::Acquire) || !self.with_auto("doc_open", |auto| Ok(auto.finish_reading(DocId(doc), prepared)))? {
            return Err(MobileError::NoDocument(doc));
        }
        // Idle reading-stage renderers (the first one starts from the reading parse) are kept only
        // while the completed document still draws the same bytes; a display copy supersedes them.
        if let Ok(display) = self.with_doc(doc, |d| d.display.clone()) {
            let mut cache = self.cache();
            if cache.get(&doc).is_some_and(|(bytes, _, _)| !pdfcraft_cos::same_storage(bytes, &display)) {
                cache.remove(&doc);
            }
        }
        Ok(ProfiledOpen { document: self.document(doc)?, timings: native_stages(&work.trace, start) })
    }

    /// Close document `doc`. Unsaved edits are refused unless `discard_changes` is set.
    pub fn close(&self, doc: u64, discard_changes: bool) -> Result<(), MobileError> {
        self.with_doc(doc, Document::cancel_preparation)?;
        self.call("doc_close", &json!({ "doc": doc, "discard_changes": discard_changes }))?;
        self.pending_opens.lock().unwrap_or_else(PoisonError::into_inner).remove(&doc);
        self.cache().remove(&doc);
        self.texts.lock().unwrap_or_else(PoisonError::into_inner).remove(&doc);
        Ok(())
    }

    /// The ids of the open documents.
    pub fn documents(&self) -> Vec<u64> {
        self.lock().session().docs().iter().map(|d| d.id.0).collect()
    }

    /// Document `doc` as it is now.
    pub fn document(&self, doc: u64) -> Result<DocumentInfo, MobileError> {
        self.with_doc(doc, document_info)
    }

    /// The editing parser's repair count, not the renderer's repairs or compatibility fallback.
    /// A count only, never the notes; detailed open timings identify other expensive stages.
    pub fn repair_count(&self, doc: u64) -> Result<u32, MobileError> {
        self.with_doc(doc, |d| u32::try_from(d.repair_log().len()).unwrap_or(u32::MAX))
    }

    /// Extra properties from the current parsed PDF. Never reads or writes the source URI.
    pub fn file_properties(&self, doc: u64) -> Result<DocumentProperties, MobileError> {
        self.with_doc(doc, |d| DocumentProperties {
            creation_date: d.info_value("CreationDate"),
            modification_date: d.info_value("ModDate"),
            custom_metadata: d.custom_info().into_iter().map(|(name, value)| MetadataField { name, value }).collect(),
            allows_modification: d.allows_modification(),
            xmp_packet: d.xmp_metadata(),
        })
    }

    /// Document `doc`'s bookmarks, flattened in reading order (at most as many as the engine reads).
    pub fn outline(&self, doc: u64) -> Result<Vec<OutlineEntry>, MobileError> {
        self.with_doc(doc, |d| {
            let mut out = Vec::new();
            flatten_outline(&d.info.outline, 0, &mut out);
            out
        })
    }

    /// Draw page `page` (0-based) of document `doc` at `scale` device pixels per point: the whole
    /// page, or only `tile` of it (device pixels at that scale). The scale is capped so that the
    /// result stays within the renderer's size limits. Sticky notes are left out: the app draws
    /// them as icons of its own.
    pub fn render_page(&self, doc: u64, page: u32, scale: f32, tile: Option<TileRect>) -> Result<RenderedImage, MobileError> {
        let out = self.render_pixels(doc, page, scale, tile)?;
        Ok(RenderedImage { width: out.width, height: out.height, rgba: out.rgba.to_vec() })
    }

    /// Optional compact opaque page previews; tiles and translucent pixels retain RGBA8.
    pub fn render_page_compact(&self, doc: u64, page: u32, scale: f32, tile: Option<TileRect>, compact: bool) -> Result<CompactImage, MobileError> {
        let out = self.render_pixels(doc, page, scale, tile)?;
        let (rgb565, pixels) = compact_pixels(&out.rgba, compact && tile.is_none());
        Ok(CompactImage { width: out.width, height: out.height, rgb565, pixels })
    }

    /// Run tool `name` with JSON arguments (`""` = none) and return its JSON result: the tools and
    /// arguments of `pdfcraft-cli run` and MCP (pages are 1-based there).
    pub fn execute(&self, name: String, args_json: String) -> Result<String, MobileError> {
        let args = if args_json.trim().is_empty() {
            Value::Null
        } else {
            serde_json::from_str(&args_json).map_err(|e| MobileError::Command(format!("`{name}`: the arguments are not valid JSON: {e}")))?
        };
        Ok(self.call(&name, &args)?.to_string())
    }

    /// Every tool, with its argument schema.
    pub fn tools(&self) -> Vec<ToolInfo> {
        pdfcraft_automation::tools()
            .into_iter()
            .map(|t| ToolInfo {
                name: t.name.to_string(),
                title: t.title.to_string(),
                description: t.description.to_string(),
                input_schema: t.input_schema.to_string(),
                read_only: t.read_only,
            })
            .collect()
    }

    /// The links on page `page`.
    pub fn links(&self, doc: u64, page: u32) -> Result<Vec<LinkInfo>, MobileError> {
        self.with_doc(doc, |d| {
            let Some(p) = d.info.pages.get(page as usize) else { return Vec::new() };
            d.info
                .links
                .iter()
                .filter(|l| l.page == page as usize)
                .filter_map(|l| {
                    let (uri, target, top) = match &l.target {
                        pdfcraft_render::LinkTarget::Uri(u) => (Some(u.clone()), None, None),
                        pdfcraft_render::LinkTarget::Page(n, view) => {
                            let top = match view {
                                pdfcraft_render::DestView::Xyz { top: Some(t), .. } | pdfcraft_render::DestView::FitH { top: Some(t) } => {
                                    d.info.pages.get(*n).map(|tp| tp.user_to_view(0.0, *t)[1])
                                }
                                _ => None,
                            };
                            (None, u32::try_from(*n).ok(), top)
                        }
                        _ => return None,
                    };
                    Some(LinkInfo { rect: view_rect(p, l.rect), uri, page: target, top })
                })
                .collect()
        })
    }

    /// Every comment of the document, page by page (replies included; see `reply_to`).
    pub fn comments(&self, doc: u64) -> Result<Vec<CommentInfo>, MobileError> {
        let snapshot = self.overlay_snapshot(doc, None)?;
        Ok(comment_records(&snapshot))
    }

    /// The files embedded in the document.
    pub fn attachments(&self, doc: u64) -> Result<Vec<AttachmentInfo>, MobileError> {
        self.with_doc(doc, |d| {
            d.info
                .attachments
                .iter()
                .map(|a| AttachmentInfo {
                    name: a.name.clone(),
                    description: a.description.clone(),
                    size: a.size.map(|s| s as u64),
                    on_page: matches!(a.source, pdfcraft_render::AttachmentSource::Annotation { .. }),
                })
                .collect()
        })
    }

    /// Write the embedded file `index` (in the order [`MobileSession::attachments`] lists them) to
    /// absolute path `path`; returns its name.
    pub fn save_attachment(&self, doc: u64, index: u32, path: String) -> Result<String, MobileError> {
        if !std::path::Path::new(&path).is_absolute() {
            return Err(MobileError::Command(format!("the path must be absolute, not `{path}`")));
        }
        let (bytes, password, att) =
            self.with_doc(doc, |d| (d.bytes.clone(), d.password.clone(), d.info.attachments.get(index as usize).cloned()))?;
        let att = att.ok_or_else(|| MobileError::Command(format!("the document has no attachment {}", index.saturating_add(1))))?;
        let data = pdfcraft_render::attachment_data(&bytes, password.as_deref(), &att).map_err(MobileError::Command)?;
        self.lock().write_output(&path, &data).map_err(|e| MobileError::Command(e.to_string()))?;
        Ok(att.name)
    }

    /// Write the recording of voice comment `index` on page `page` (as [`MobileSession::comments`]
    /// numbers them) to absolute path `path` as a WAV file, for the player.
    pub fn save_sound(&self, doc: u64, page: u32, index: u32, path: String) -> Result<(), MobileError> {
        if !std::path::Path::new(&path).is_absolute() {
            return Err(MobileError::Command(format!("the path must be absolute, not `{path}`")));
        }
        let (bytes, password) = self.with_doc(doc, |d| (d.bytes.clone(), d.password.clone()))?;
        let wav = pdfcraft_render::sound_wav(&bytes, password.as_deref(), page as usize, index as usize).map_err(MobileError::Command)?;
        self.lock().write_output(&path, &wav).map(|_| ()).map_err(|e| MobileError::Command(e.to_string()))
    }

    /// The certificate (DER) that signed signature field `field`, if it is signed: what the app
    /// saves when the reader chooses to trust that signer.
    pub fn signer_certificate(&self, doc: u64, field: String) -> Result<Option<Vec<u8>>, MobileError> {
        self.with_doc(doc, |d| d.signatures.iter().find(|s| s.signed && s.field == field).and_then(|s| s.certificate.as_ref()).map(|c| c.raw.clone()))
    }

    /// Every visible widget of the document's form fields, page by page.
    pub fn widgets(&self, doc: u64) -> Result<Vec<WidgetInfo>, MobileError> {
        let snapshot = self.overlay_snapshot(doc, Some(&[]))?;
        Ok(widget_records(&snapshot, None))
    }

    /// A bounded batch of visible-page overlays, carrying their source generation.
    pub fn page_overlays(&self, doc: u64, pages: Vec<u32>) -> Result<PageOverlays, MobileError> {
        if pages.len() > 16 {
            return Err(MobileError::Command("At most 16 overlay pages may be requested".into()));
        }
        let mut pages: Vec<usize> = pages.into_iter().map(|p| p as usize).collect();
        pages.sort_unstable();
        pages.dedup();
        let snapshot = self.overlay_snapshot(doc, Some(&pages))?;
        if pages.iter().any(|&p| p >= snapshot.pages.len()) {
            return Err(MobileError::Command("Overlay page is out of range".into()));
        }
        Ok(PageOverlays {
            generation: snapshot.generation,
            pages: pages.iter().map(|&p| p as u32).collect(),
            comments: comment_records(&snapshot),
            widgets: widget_records(&snapshot, Some(&pages)),
        })
    }

    /// Drop the idle renderers and text layers (the system is short of memory); the next render
    /// or text call makes new ones.
    pub fn release_memory(&self) {
        self.cache().clear();
        self.texts.lock().unwrap_or_else(PoisonError::into_inner).clear();
    }

    /// The word at point (`x`, `y`) on page `page` (points, top-left origin), or the one nearest it
    /// within `slop` points: what a long press selects.
    pub fn word_at(&self, doc: u64, page: u32, x: f32, y: f32, slop: f32) -> Result<Option<TextRange>, MobileError> {
        let text = self.page_text(doc, page)?;
        let Some(i) = text.nearest(x, y) else { return Ok(None) };
        let Some(g) = text.glyphs.get(i) else { return Ok(None) };
        let [x0, y0, x1, y1] = g.rect;
        let slop = if slop.is_finite() { slop.max(0.0) } else { 0.0 };
        if x < x0 - slop || x > x1 + slop || y < y0 - slop || y > y1 + slop {
            return Ok(None);
        }
        Ok(text.word_at(i).map(|(s, e)| TextRange { page, start: s as u32, end: e.saturating_add(1) as u32 }))
    }

    /// The glyph nearest point (`x`, `y`) on page `page`: where a selection handle lands.
    pub fn nearest_glyph(&self, doc: u64, page: u32, x: f32, y: f32) -> Result<Option<u32>, MobileError> {
        Ok(self.page_text(doc, page)?.nearest(x, y).and_then(|i| u32::try_from(i).ok()))
    }

    /// How many glyphs page `page` has (0: no text, e.g. a scan without OCR).
    pub fn glyph_count(&self, doc: u64, page: u32) -> Result<u32, MobileError> {
        Ok(u32::try_from(self.page_text(doc, page)?.glyphs.len()).unwrap_or(u32::MAX))
    }

    /// The rectangles covering `range`, one per line (flattened `x0, y0, x1, y1`, points).
    pub fn text_rects(&self, doc: u64, range: TextRange) -> Result<Vec<f32>, MobileError> {
        let text = self.page_text(doc, range.page)?;
        Ok(flatten_rects(&text.line_rects(glyph_range(&text, range.start, range.end))))
    }

    /// The rectangle of glyph `index` on page `page` (`x0, y0, x1, y1`): where a selection handle sits.
    pub fn glyph_rect(&self, doc: u64, page: u32, index: u32) -> Result<Vec<f32>, MobileError> {
        let text = self.page_text(doc, page)?;
        Ok(text.glyphs.get(index as usize).map(|g| g.rect.to_vec()).unwrap_or_default())
    }

    /// The text of `range`, with spaces and line breaks.
    pub fn text_of(&self, doc: u64, range: TextRange) -> Result<String, MobileError> {
        let text = self.page_text(doc, range.page)?;
        Ok(text.text_of(glyph_range(&text, range.start, range.end)))
    }

    /// Page `page`'s text as paragraphs in reading order (Read Aloud). A new paragraph starts
    /// where a line sits clearly lower than the line before would lead on to (a gap of over half
    /// a line), goes back up (a new column), or is set in a markedly different size.
    pub fn reading_blocks(&self, doc: u64, page: u32) -> Result<Vec<ReadingBlock>, MobileError> {
        let text = self.page_text(doc, page)?;
        Ok(reading_blocks(&text, page))
    }

    /// All of page `page`'s text (Read Aloud, select all).
    pub fn page_plain_text(&self, doc: u64, page: u32) -> Result<String, MobileError> {
        Ok(self.page_text(doc, page)?.plain_text())
    }

    /// Where `query` occurs on page `page`. The app searches page by page so it can show hits as
    /// they come and stop when the reader moves on.
    pub fn find_in_page(&self, doc: u64, page: u32, query: String, case_sensitive: bool, whole_words: bool) -> Result<Vec<SearchHit>, MobileError> {
        if query.trim().is_empty() {
            return Ok(Vec::new());
        }
        let text = self.page_text(doc, page)?;
        Ok(text
            .find_opts(&query, case_sensitive, whole_words)
            .into_iter()
            .map(|r| {
                let context = text.line_at(r.start).map(|(s, e)| text.text_of(s..e.saturating_add(1))).unwrap_or_default();
                SearchHit { range: TextRange { page, start: r.start as u32, end: r.end as u32 }, rects: flatten_rects(&text.line_rects(r)), context }
            })
            .collect())
    }
}

/// The first JSON result of a tool (`null` if it gave none).
fn first_json(out: Vec<Content>) -> Value {
    out.into_iter()
        .find_map(|c| match c {
            Content::Json(v) => Some(v),
            Content::Png { .. } => None,
        })
        .unwrap_or(Value::Null)
}

/// How pages of `d` are drawn here: the app draws sticky notes itself, as fixed-size icons over
/// the page.
/// The page raster configuration: the document's view settings (hidden comments, layer
/// visibility, reading colours), with sticky-note icons left to the app's overlay. Installed CJK
/// faces stay off, as before, so the raster does not depend on the phone's fonts.
fn page_render_config(d: &Document, view: &RenderConfig) -> RenderConfig {
    RenderConfig {
        password: d.password.as_deref().map(Arc::from),
        layers: view.layers.clone(),
        hide_comments: d.comments_hidden(),
        reading_colors: view.reading_colors,
        hide_notes: true,
        ..RenderConfig::default()
    }
}

/// What tells two renderer configurations apart, without the password.
fn config_key(c: &RenderConfig) -> String {
    format!(
        "{:?}|{}|{}|{}|{:?}|{}|{}|{:?}|{:?}",
        c.layers, c.hide_comments, c.hide_notes, c.reject_oversize, c.reading_colors, c.transparent, c.system_fonts, c.jbig2_work, c.print_layers
    )
}

fn native_stages(trace: &pdfcraft_render::OpenTrace, start: usize) -> Vec<NativeOpenTiming> {
    trace.snapshot().into_iter().skip(start).map(|s| NativeOpenTiming { stage: s.name.into(), duration_ms: s.duration_ms }).collect()
}

fn open_native_error(error: OpenError) -> MobileError {
    match error {
        OpenError::NeedsPassword => MobileError::NeedsPassword,
        OpenError::WrongPassword => MobileError::WrongPassword,
        other => MobileError::Open(other.to_string()),
    }
}

/// Run `f`; a panic in it becomes a [`MobileError::Command`] that says `what` stopped (#114).
fn catch_panic<T>(what: &str, f: impl FnOnce() -> Result<T, MobileError>) -> Result<T, MobileError> {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).unwrap_or_else(|payload| {
        let detail =
            payload.downcast_ref::<&str>().map(|s| (*s).to_owned()).or_else(|| payload.downcast_ref::<String>().cloned()).unwrap_or_default();
        log::error!("internal error in {what}: {detail}");
        Err(MobileError::Command(format!("An internal error stopped this action ({what}). If the document looks wrong, close it and open it again.")))
    })
}

/// A failed `doc_open`, with the password cases told apart so the app can ask for one.
fn open_error(e: ToolError) -> MobileError {
    let message = e.to_string();
    if message == OpenError::NeedsPassword.to_string() {
        MobileError::NeedsPassword
    } else if message == OpenError::WrongPassword.to_string() {
        MobileError::WrongPassword
    } else {
        MobileError::Open(message)
    }
}

fn document_info(d: &Document) -> DocumentInfo {
    let info = &d.info;
    DocumentInfo {
        id: d.id.0,
        name: d.name.clone(),
        path: d.path.clone(),
        pages: info.pages.iter().map(|p| PageInfo { width: p.width, height: p.height, label: p.label.clone(), rotation: p.rotation }).collect(),
        title: info.title.clone(),
        author: info.author.clone(),
        subject: info.subject.clone(),
        keywords: info.keywords.clone(),
        creator: info.creator.clone(),
        producer: info.producer.clone(),
        pdf_version: info.pdf_version.clone(),
        file_size: info.file_size as u64,
        encrypted: info.encrypted,
        tagged: info.tagged,
        read_only_reason: d.read_only_reason.clone(),
        preparing: d.preparing(),
        allows_printing: d.allows_printing(),
        allows_copying: d.allows_copying(),
        allows_annotation: d.allows_annotation(),
        allows_form_filling: d.allows_form_filling(),
        allows_assembly: d.allows_assembly(),
        dirty: d.dirty,
        undo: d.can_undo().map(str::to_string),
        redo: d.can_redo().map(str::to_string),
        fields: u32::try_from(d.form.len()).unwrap_or(u32::MAX),
        has_outline: !info.outline.is_empty(),
        // the document's own files: those on comments are reached through the comment
        attachments: u32::try_from(
            info.attachments.iter().filter(|a| matches!(a.source, pdfcraft_render::AttachmentSource::Document { .. })).count(),
        )
        .unwrap_or(u32::MAX),
        signed: d.is_signed(),
        comments_hidden: d.comments_hidden(),
        generation: d.edit_generation(),
    }
}

/// How deep the flattened outline goes (the engine already bounds what it reads).
const OUTLINE_DEPTH: u32 = 32;

fn flatten_outline(items: &[pdfcraft_render::OutlineItem], level: u32, out: &mut Vec<OutlineEntry>) {
    if level > OUTLINE_DEPTH {
        return;
    }
    for item in items {
        out.push(OutlineEntry {
            title: item.title.clone(),
            level,
            page: item.page.and_then(|p| u32::try_from(p).ok()),
            children: u32::try_from(item.children.len()).unwrap_or(u32::MAX),
        });
        flatten_outline(&item.children, level.saturating_add(1), out);
    }
}

